"""Recount the frozen Yale geometric support after QC-screened face recovery."""

import argparse
from collections import defaultdict
import json
import math
from pathlib import Path
import re
import sys


ROOT = Path(__file__).resolve().parent
BASELINE = ROOT.parent / "voynich-mate-support-work"
sys.path.insert(0, str(BASELINE))
from audit_support import compare_counts, groups_to_pairs, physical_map


PAGE = re.compile(r"(f\d+)([rv])")
ERROR_CUTOFF = 1.8199963569641113
SUPPORT_FLOOR = 8

QC_RULES = {
    "train_inliers": (40, None),
    "train_inlier_fraction": (0.50, 1.0),
    "heldout_matches": (20, None),
    "heldout_median_error_px": (0.0, 2.0),
    "heldout_p90_error_px": (0.0, 5.0),
    "heldout_within_5px": (0.80, 1.0),
    "box_center_hull_coverage": (0.80, 1.0),
}


def load_archive():
    manifest = json.loads((ROOT / "archived-yale-summary.json").read_text())["manifest"]
    archived = {
        row["page"]: {
            "passed": str(row["registration_passed"]),
            "heldout_p90_error_px": row["registration"]["heldout_p90_error_px"],
        }
        for row in manifest
    }
    crops = {row["page"]: row["valid_crops"] for row in manifest if row["registration_passed"]}
    assert len(manifest) == len(archived) == 181
    assert len(crops) == 143
    return archived, crops


def record_support(metadata, physical_mates, tiers, crop_counts):
    sides = defaultdict(dict)
    deep_sides = defaultdict(dict)
    for page, tier in tiers.items():
        leaf, side = PAGE.fullmatch(page).groups()
        sides[leaf][side] = tier
        if crop_counts.get(page, 0) >= 20:
            deep_sides[leaf][side] = tier

    def complete_leaf_quality(available):
        return {leaf: (face["r"], face["v"]) for leaf, face in available.items() if len(face) == 2}

    quality = complete_leaf_quality(sides)
    deep_quality = complete_leaf_quality(deep_sides)
    summary = compare_counts(metadata, physical_mates, set(quality), quality)
    deep_summary = compare_counts(metadata, physical_mates, set(deep_quality), deep_quality)
    return summary, deep_summary


def counts_and_pairs(summary):
    return {
        "eligible_leaves": summary["eligible_leaves"],
        "eligible_mates": summary["eligible_mates"],
        "informative_mates": summary["informative_mates"],
        "informative_quires": sorted({row["quire"] for row in summary["mate_rows"]}),
        "informative_mates_with_disjoint_control": summary["informative_mates_with_disjoint_control"],
        "informative_quires_with_disjoint_control": sorted({
            row["quire"] for row in summary["mate_rows"] if row["disjoint_nonmates"]
        }),
        "pairs": [
            {
                "quire": row["quire"],
                "mate": row["mate"],
                "folio_span": int(row["mate"][1][1:]) - int(row["mate"][0][1:]),
                "quality_signature": row["quality_signature"],
                "nonmates": row["nonmates"],
                "disjoint_nonmates": [pair for pair in row["nonmates"] if set(pair).isdisjoint(row["mate"])],
            }
            for row in summary["mate_rows"]
        ],
    }


def check_qc(row):
    failed = []
    for key, (lower, upper) in QC_RULES.items():
        value = row.get(key)
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
            failed.append(f"missing_or_invalid:{key}")
        elif value < lower or (upper is not None and value > upper):
            failed.append(f"outside_qc_range:{key}")
    for key in ("train_inliers", "heldout_matches"):
        value = row.get(key)
        if isinstance(value, float) and math.isfinite(value) and not value.is_integer():
            failed.append(f"not_an_integer_count:{key}")
    matches = row.get("ratio_matches")
    if matches is not None and (type(matches) is not int or matches < 80):
        failed.append("outside_qc_range:ratio_matches")
    width, height = row.get("qc_width"), row.get("qc_height")
    if (width is not None or height is not None) and (
        type(width) is not int or type(height) is not int or min(width, height) <= 0 or max(width, height) != 1600
    ):
        failed.append("not_full_page_1600px_qc_scale")
    if row.get("passed") is False:
        failed.append("registration_declared_failed")
    crop_count = row.get("n_valid_crops")
    if crop_count is not None and (type(crop_count) is not int or crop_count < 1):
        failed.append("no_verified_crops")
    return failed


def existing_or_excluded(archive, page):
    if page not in archive:
        return "not_an_archived_candidate"
    if archive[page]["passed"] == "True":
        return "archived_registration_already_passed"
    return None


def process_faces(faces, archive, initial, archived_crops):
    tiers = dict(initial)
    crop_counts = dict(archived_crops)
    outcomes = {}
    for row in faces:
        page = row["page"]
        if page in outcomes:
            raise ValueError(f"multiple replacement rows for {page}")
        exclusion = existing_or_excluded(archive, page)
        if exclusion:
            outcomes[page] = {"accepted": False, "reasons": [exclusion]}
            continue
        failures = check_qc(row)
        if failures:
            outcomes[page] = {"accepted": False, "reasons": failures}
            continue
        tier = int(row["heldout_p90_error_px"] > ERROR_CUTOFF)
        tiers[page] = tier
        if row.get("n_valid_crops") is not None:
            crop_counts[page] = row["n_valid_crops"]
        outcomes[page] = {"accepted": True, "quality_tier": tier, "n_valid_crops": crop_counts.get(page)}
    return tiers, crop_counts, outcomes


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("registrations", type=Path, nargs="?", help="JSON array or object with a faces array")
    parser.add_argument("--options", type=Path, help="JSON object mapping scenarios to hypothesized per-face tiers")
    args = parser.parse_args()

    metadata = physical_map()
    physical_mates = groups_to_pairs(metadata, set(metadata))
    archive, archived_crops = load_archive()
    initial = {page: int(float(archive[page]["heldout_p90_error_px"]) > ERROR_CUTOFF) for page in archived_crops}
    baseline, _ = record_support(metadata, physical_mates, initial, archived_crops)
    assert baseline["informative_mates"] == 7 and baseline["informative_quires"] == 6
    assert baseline["informative_mates_with_disjoint_control"] == 6
    assert baseline["informative_quires_with_disjoint_control"] == 5

    output = {
        "yale_frozen_p90_cutoff_px": ERROR_CUTOFF,
        "support_floor_quires": SUPPORT_FLOOR,
        "baseline": counts_and_pairs(baseline),
    }

    if args.registrations:
        rows = json.loads(args.registrations.read_text())
        faces = rows["faces"] if isinstance(rows, dict) else rows
        tiers, crops, outcomes = process_faces(faces, archive, initial, archived_crops)
        summary, deep_summary = record_support(metadata, physical_mates, tiers, crops)
        output["observed_rescue"] = {
            "replacement_outcomes": outcomes,
            "geometric_support": counts_and_pairs(summary),
            "at_least_20_verified_crops_per_face": counts_and_pairs(deep_summary),
            "geometric_floor_met": summary["informative_quires"] >= SUPPORT_FLOOR,
        }

    if args.options:
        output["hypothetical_options"] = {}
        for name, additions in json.loads(args.options.read_text()).items():
            for page, tier in additions.items():
                if existing_or_excluded(archive, page) or type(tier) is not int or tier not in (0, 1):
                    raise ValueError(f"invalid hypothetical face tier in {name}: {page}={tier}")
            summary, _ = record_support(metadata, physical_mates, initial | additions, archived_crops)
            output["hypothetical_options"][name] = {"assumed_tiers": additions, **counts_and_pairs(summary)}

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
